package analysis

// classify_test.go — assertion tables ported from tests/unit/test_ai_usage.py
// (TestClassifyAiMarkers, TestClassifyAiAuthors, TestClassifyAiItem,
// TestAggregate), plus golden pins for the unicode-boundary traps and
// byte-exact wire pins generated by the Python reference
// (json.dumps(signal_to_wire(aggregate_ai_markers(items))) and
// json.dumps(_collect_samples(items, limit=None))). Non-ASCII literals are
// spelled as escapes so gofmt output stays stable.

import (
	"reflect"
	"sort"
	"strings"
	"testing"

	"github.com/yeaboi-ai/yeaboi/go/internal/pysem"
)

func toolSet(ids ...string) map[string]bool {
	out := map[string]bool{}
	for _, id := range ids {
		out[id] = true
	}
	return out
}

func assertTools(t *testing.T, name string, got, want map[string]bool) {
	t.Helper()
	if !reflect.DeepEqual(got, want) {
		t.Errorf("%s: got %v, want %v", name, got, want)
	}
}

// --- TestClassifyAiMarkers ------------------------------------------------

func TestClassifyAiMarkers(t *testing.T) {
	cases := []struct {
		name string
		text string
		want map[string]bool
	}{
		{"claude co-author", "feat\n\nCo-Authored-By: Claude <noreply@anthropic.com>", toolSet("claude")},
		{"claude generated with",
			"\U0001f916 Generated with [Claude Code](https://claude.com/claude-code)", toolSet("claude")},
		{"copilot", "Co-authored-by: Copilot <copilot@github.com>", toolSet("copilot")},
		{"cursor", "Co-authored-by: Cursor Agent <agent@cursor.com>", toolSet("cursor")},
		{"aider", "aider: refactor module\n\nCo-authored-by: aider (gpt-4)", toolSet("aider")},
		{"devin", "Co-authored-by: Devin AI <devin-ai-integration[bot]@users.noreply>", toolSet("devin")},
		{"codeium via windsurf", "Generated with Windsurf", toolSet("codeium")},
		{"aider author suffix", "refactor helpers (aider)", toolSet("aider")},
		{"aider chat link", "see https://aider.chat for details", toolSet("aider")},
		{"chatgpt co-author is other_ai", "fix\n\nCo-authored-by: ChatGPT <noreply@openai.com>", toolSet("other_ai")},
		// Regression: bare product names in prose used to count as AI authorship.
		{"windsurf prose", "Add windsurf integration page", toolSet()},
		{"codeium prose", "Document codeium comparison for the wiki", toolSet()},
		{"aider and cursor prose", "Refactor aider docs and cursor bindings", toolSet()},
		{"devin prose", "work by devin-ai on the roadmap", toolSet()},
		// Regression: dependency-automation co-authors inflated the footprint.
		{"dependabot", "bump deps\n\nCo-authored-by: dependabot[bot] <support@github.com>", toolSet()},
		{"renovate", "chore\n\nCo-authored-by: renovate[bot] <bot@renovateapp.com>", toolSet()},
		{"github-actions", "ci\n\nCo-authored-by: github-actions[bot] <actions@github.com>", toolSet()},
		{"generic non-AI bot", "merge\n\nCo-authored-by: my-team-bot <bot@example.com>", toolSet()},
		{"generic other_ai", "Co-Authored-By: Some Assistant <bot@x.com>", toolSet("other_ai")},
		{"no match", "just a normal commit message", toolSet()},
		{"empty", "", toolSet()},
		{"specific suppresses other_ai", "Co-Authored-By: Claude\nCo-Authored-By: some bot", toolSet("claude")},
		{"codex co-author", "fix\n\nCo-authored-by: Codex <bot@openai.com>", toolSet("codex")},
		{"codex task link", "Summary\n\nhttps://chatgpt.com/codex/tasks/task_e_123", toolSet("codex")},
		{"codex generated by", "docs\n\nGenerated by Codex", toolSet("codex")},
		{"codex prose mention", "we evaluated codex for the team", toolSet()},
		{"two specific tools", "Co-authored-by: aider\nCo-authored-by: Copilot", toolSet("aider", "copilot")},
		// Python's \s is unicode: a no-break space or a newline after the
		// colon still reaches the claude literal.
		{"nbsp after colon", "Co-Authored-By:\u00a0Claude", toolSet("claude")},
		{"newline after colon", "Co-Authored-By:\nClaude wrote this", toolSet("claude")},
		// Python's \b is unicode: U+00E9 glued to a tool word kills the
		// boundary that the ASCII engine would still see.
		{"unicode rune before codex", "Co-authored-by: \u00e9codex helper", toolSet()},
		{"unicode rune after codex", "Co-authored-by: codex\u00e9 helper", toolSet()},
		{"aider subject after crlf", "subject\r\n  AIDER: tidy", toolSet("aider")},
	}
	for _, tc := range cases {
		assertTools(t, tc.name, classifyAiMarkers(tc.text), tc.want)
	}
}

// --- TestClassifyAiAuthors ------------------------------------------------

func TestClassifyAiAuthors(t *testing.T) {
	cases := []struct {
		name          string
		author, email string
		want          map[string]bool
	}{
		{"devin bot account", "devin-ai-integration[bot]", "", toolSet("devin")},
		{"copilot swe agent", "copilot-swe-agent[bot]", "", toolSet("copilot")},
		{"plain copilot", "Copilot", "", toolSet("copilot")},
		{"openai codex bot", "openai-codex[bot]", "", toolSet("codex")},
		{"codex connector", "chatgpt-codex-connector[bot]", "", toolSet("codex")},
		{"cursor agent", "Cursor Agent", "", toolSet("cursor")},
		{"jules", "google-labs-jules[bot]", "", toolSet("gemini")},
		{"claude email", "Claude", "noreply@anthropic.com", toolSet("claude")},
		{"cursor email", "someone", "cursoragent@cursor.com", toolSet("cursor")},
		{"devin email", "bot", "devin-ai-integration@devin.ai", toolSet("devin")},
		{"aider author suffix", "Ava Lee (aider)", "", toolSet("aider")},
		{"human devin", "Devin Smith", "devin.smith@example.com", toolSet()},
		{"human claudette", "Claudette Marchand", "claudette@example.com", toolSet()},
		{"human ava", "Ava", "ava@example.com", toolSet()},
		{"dependabot", "dependabot[bot]", "", toolSet()},
		{"renovate", "renovate[bot]", "", toolSet()},
		{"unknown ai bot is other_ai", "some-ai-agent[bot]", "", toolSet("other_ai")},
		{"empty", "", "", toolSet()},
		{"strip before matching", "  devin-ai-integration[bot]  ", "", toolSet("devin")},
	}
	for _, tc := range cases {
		assertTools(t, tc.name, classifyAiAuthors(tc.author, tc.email), tc.want)
	}
}

// --- TestClassifyAiItem ---------------------------------------------------

func TestClassifyAiItem(t *testing.T) {
	cases := []struct {
		name string
		item *pysem.Obj
		want map[string]bool
	}{
		{"codex branch prefix",
			practItem("kind", "pr", "title", "Fix login", "branch", "codex/fix-login"), toolSet("codex")},
		{"copilot branch prefix",
			practItem("kind", "pr", "title", "Add tests", "branch", "copilot/add-tests"), toolSet("copilot")},
		{"human branch with codex word",
			practItem("kind", "pr", "title", "Docs", "branch", "feature/codex-docs"), toolSet()},
		{"human branch with cursor word",
			practItem("kind", "pr", "title", "Style", "branch", "fix-cursor-styles"), toolSet()},
		{"author and text union",
			practItem("kind", "commit", "author", "devin-ai-integration[bot]",
				"title", "fix", "body", "Co-Authored-By: Claude"),
			toolSet("claude", "devin")},
		{"null title and body render as None",
			practItem("kind", "commit", "title", nil, "body", nil), toolSet()},
	}
	for _, tc := range cases {
		assertTools(t, tc.name, ClassifyAiItem(tc.item), tc.want)
	}
}

// --- TestAggregate --------------------------------------------------------

// aggregateFixture mirrors tests/unit/test_ai_usage.py::TestAggregate
// test_buckets_and_footprint.
const aggregateFixture = `[
  {"kind": "commit", "author": "Alice", "title": "feat", "body": "Co-Authored-By: Claude", "source": "gh"},
  {"kind": "commit", "author": "Bob", "title": "docs: update README", "body": "", "source": "local_git"},
  {"kind": "pr", "author": "Alice", "title": "Add feature", "body": "Generated with Claude Code", "source": "gh"}
]`

// aggregateExpected is json.dumps(signal_to_wire(aggregate_ai_markers(items)))
// from the Python reference — byte-exact, signal key order contractual.
const aggregateExpected = `{"scanned_commits": 2, "scanned_prs": 1, "ai_commits": 1, "ai_prs": 1, ` +
	`"footprint_pct": 66.7, "per_tool": [["claude", 2]], "per_author": [["Alice", 2]], ` +
	`"per_activity": [["code", 1], ["pr", 1]], "per_source": [["gh", 2]], ` +
	`"sources_scanned": ["gh", "local_git"], "is_lower_bound": true}`

func TestAggregateMatchesThePythonReferenceByteForByte(t *testing.T) {
	items := decodeItems(t, aggregateFixture)
	got := pysem.JSONDumps(AggregateAiMarkers(items))
	if got != aggregateExpected {
		t.Fatalf("wire mismatch:\n got: %s\nwant: %s", got, aggregateExpected)
	}
}

func TestAggregateEmpty(t *testing.T) {
	want := `{"scanned_commits": 0, "scanned_prs": 0, "ai_commits": 0, "ai_prs": 0, "footprint_pct": 0.0, ` +
		`"per_tool": [], "per_author": [], "per_activity": [], "per_source": [], "sources_scanned": [], ` +
		`"is_lower_bound": true}`
	got := pysem.JSONDumps(AggregateAiMarkers([]any{}))
	if got != want {
		t.Fatalf("wire mismatch:\n got: %s\nwant: %s", got, want)
	}
}

// Count ties break alphabetically ((-count, name) — Python reference output).
func TestAggregatePairOrderingTies(t *testing.T) {
	items := decodeItems(t, `[
	  {"kind": "commit", "author": "Zoe", "title": "x", "body": "Co-Authored-By: Claude", "source": "azdo"},
	  {"kind": "pr", "author": "Al", "title": "y", "body": "Generated by Codex", "source": "github"}
	]`)
	want := `{"scanned_commits": 1, "scanned_prs": 1, "ai_commits": 1, "ai_prs": 1, "footprint_pct": 100.0, ` +
		`"per_tool": [["claude", 1], ["codex", 1]], "per_author": [["Al", 1], ["Zoe", 1]], ` +
		`"per_activity": [["code", 1], ["pr", 1]], "per_source": [["azdo", 1], ["github", 1]], ` +
		`"sources_scanned": ["azdo", "github"], "is_lower_bound": true}`
	got := pysem.JSONDumps(AggregateAiMarkers(items))
	if got != want {
		t.Fatalf("wire mismatch:\n got: %s\nwant: %s", got, want)
	}
}

func TestAggregateIgnoresNonCommitPrKinds(t *testing.T) {
	items := decodeItems(t, `[{"kind": "page", "title": "x", "body": "Co-Authored-By: Claude"}]`)
	out := AggregateAiMarkers(items)
	if out.Get("scanned_commits").(int64) != 0 || out.Get("scanned_prs").(int64) != 0 {
		t.Fatalf("non-commit/pr kinds must be ignored: %s", pysem.JSONDumps(out))
	}
}

func TestAggregateDocsBucket(t *testing.T) {
	items := decodeItems(t, `[{"kind": "commit", "author": "A", "title": "docs: add guide.md",
		"body": "Co-Authored-By: Claude"}]`)
	out := AggregateAiMarkers(items)
	want := []any{[]any{"docs", int64(1)}}
	if !reflect.DeepEqual(out.Get("per_activity"), want) {
		t.Fatalf("got per_activity %v, want %v", out.Get("per_activity"), want)
	}
}

// Agents that commit under their own account often leave no trailer.
func TestAggregateBotAuthoredPlainMessageCounts(t *testing.T) {
	items := decodeItems(t, `[{"kind": "commit", "author": "devin-ai-integration[bot]",
		"title": "fix flaky test", "body": ""}]`)
	out := AggregateAiMarkers(items)
	if out.Get("ai_commits").(int64) != 1 {
		t.Fatalf("bot-authored commit not counted: %s", pysem.JSONDumps(out))
	}
	want := []any{[]any{"devin", int64(1)}}
	if !reflect.DeepEqual(out.Get("per_tool"), want) {
		t.Fatalf("got per_tool %v, want %v", out.Get("per_tool"), want)
	}
}

// --- TestCollectSamples ---------------------------------------------------

func samplesFixture() []any {
	title := strings.Repeat("\u00e9", 50) + strings.Repeat("x", 50)
	return []any{
		practItem("kind", "commit", "author", "  ", "title", title,
			"body", "Co-Authored-By: Claude", "source", "gh", "key", "abc123", "url", "https://x/y"),
		practItem("kind", "pr", "author", "devin-ai-integration[bot]", "title", "fix",
			"body", "Co-Authored-By: Claude", "branch", "codex/z"),
		practItem("kind", "commit", "author", "Human", "title", "plain", "body", ""),
	}
}

// samplesExpected is json.dumps(_collect_samples(items, limit=None)) from the
// Python reference: the blank author reads "unknown", the tool is
// sorted(tools)[0] ("claude" beats "codex"/"devin" on the second item), and
// the 100-code-point title is cut at 80 CODE POINTS (50 two-byte runes + 30
// ASCII), never at 80 bytes.
const samplesExpected = `[{"author": "unknown", "tool": "claude", "activity": "code", "title": "` +
	`\u00e9\u00e9\u00e9\u00e9\u00e9\u00e9\u00e9\u00e9\u00e9\u00e9\u00e9\u00e9\u00e9\u00e9\u00e9\u00e9` +
	`\u00e9\u00e9\u00e9\u00e9\u00e9\u00e9\u00e9\u00e9\u00e9\u00e9\u00e9\u00e9\u00e9\u00e9\u00e9\u00e9` +
	`\u00e9\u00e9\u00e9\u00e9\u00e9\u00e9\u00e9\u00e9\u00e9\u00e9\u00e9\u00e9\u00e9\u00e9\u00e9\u00e9` +
	`\u00e9\u00e9xxxxxxxxxxxxxxxxxxxxxxxxxxxxxx", "source": "gh", "key": "abc123", "url": "https://x/y"}, ` +
	`{"author": "devin-ai-integration[bot]", "tool": "claude", "activity": "pr", "title": "fix", ` +
	`"source": "", "key": "", "url": ""}]`

func TestCollectSamplesMatchesThePythonReferenceByteForByte(t *testing.T) {
	got := pysem.JSONDumps(CollectSamples(samplesFixture(), -1))
	if got != samplesExpected {
		t.Fatalf("wire mismatch:\n got: %s\nwant: %s", got, samplesExpected)
	}
}

func TestCollectSamplesLimit(t *testing.T) {
	out := CollectSamples(samplesFixture(), 1)
	if len(out) != 1 {
		t.Fatalf("got %d samples, want 1", len(out))
	}
	title := out[0].(*pysem.Obj).Get("title").(string)
	if got := len([]rune(title)); got != 80 {
		t.Fatalf("title truncated to %d code points, want 80", got)
	}
}

// --- Aggregate over the marker classifier's set ---------------------------

func TestClassifierReturnsSortableSet(t *testing.T) {
	// The second samples item unions three tools; sorted(tools)[0] must be
	// stable regardless of Go map iteration order.
	tools := ClassifyAiItem(samplesFixture()[1].(*pysem.Obj))
	names := []string{}
	for id := range tools {
		names = append(names, id)
	}
	sort.Strings(names)
	want := []string{"claude", "codex", "devin"}
	if !reflect.DeepEqual(names, want) {
		t.Fatalf("got %v, want %v", names, want)
	}
}
